// A trimmed Shopify orders/paid payload. Run the workflow with "Test workflow" to see every step without a real order.
return [{ json: { sample: true, body: {
  id: 820982911946154500, name: '#1001', tags: '', note: 'Leave at the side door',
  shipping_address: { first_name: 'Sam', last_name: 'Lee', address1: '12 Main St', city: 'Springfield', province_code: 'MA', zip: '01103', country_code: 'US' },
  shipping_lines: [{ title: 'Standard Shipping' }],
  line_items: [
    { quantity: 2, sku: 'MUG-BLU', title: 'Mug', variant_title: 'Blue', requires_shipping: true, properties: [{ name: 'Gift wrap', value: 'Yes' }] },
    { quantity: 1, sku: '', title: 'Gift card', requires_shipping: false }
  ] } } }];

// Checks Shopify's X-Shopify-Hmac-Sha256 header against the raw body. Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.
// The sample order skips the check.
const crypto = require('crypto');
const cfg = $('Config').first().json, out = [];
for (let i = 0; i < $input.all().length; i++) {
  const it = $input.all()[i];
  if (it.json.sample) { out.push({ json: { valid: true, order: it.json.body } }); continue; }
  let valid = false, order = it.json.body || {};
  try {
    const raw = await this.helpers.getBinaryDataBuffer(i, 'data');
    const sent = String((it.json.headers || {})['x-shopify-hmac-sha256'] || '');
    const calc = crypto.createHmac('sha256', cfg.shopify_webhook_secret).update(raw).digest('base64');
    valid = sent.length === calc.length && crypto.timingSafeEqual(Buffer.from(sent), Buffer.from(calc));
    if (!order.id) order = JSON.parse(raw.toString('utf8'));
  } catch (e) { valid = false; }
  out.push({ json: { valid, order, ref: order.name || '' } });
}
return out;

// Field mapping lives in Config: skip tags, SKU field, missing-SKU text, line properties and shipping names.
const cfg = $('Config').first().json;
const skipTags = String(cfg.skip_tags || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
let shipMap = {}; try { shipMap = JSON.parse(cfg.shipping_map || '{}'); } catch (e) {}
return $input.all().map(i => {
  const o = i.json.order || {}, a = o.shipping_address || {};
  const tags = String(o.tags || '').toLowerCase().split(',').map(s => s.trim());
  const lines = (o.line_items || []).filter(l => l.requires_shipping !== false);
  const props = l => String(cfg.include_line_properties) === 'true' && (l.properties || []).length ? ' [' + l.properties.map(p => p.name + ': ' + p.value).join(', ') + ']' : '';
  const pick = lines.map(l => `${l.quantity} x ${l[cfg.sku_field] || cfg.missing_sku_text}  ${l.title}${l.variant_title ? ' (' + l.variant_title + ')' : ''}${props(l)}`);
  const ship = (o.shipping_lines || []).map(s => shipMap[s.title] || s.title).join(', ') || 'Standard';
  const skip = skipTags.find(t => tags.includes(t)) ? 'tagged ' + skipTags.find(t => tags.includes(t))
    : (!lines.length && String(cfg.skip_if_no_shipping) === 'true') ? 'nothing to ship' : '';
  return { json: { order_id: String(o.id || ''), ref: o.name || String(o.id || ''), skip,
    customer: [a.first_name, a.last_name].filter(Boolean).join(' '), company: a.company || '', phone: a.phone || '',
    ship_to: [a.address1, a.address2, a.city, a.province_code, a.zip, a.country_code].filter(Boolean).join(', '),
    shipping: ship, note: o.note || '', pick_list: pick.join('\n'), lines: pick.length,
    missing_sku: lines.some(l => !l[cfg.sku_field]) } };
});

// Idempotency: order ids already sent are kept in the workflow's static data (saved on production runs only),
// so a webhook Shopify delivers twice, or a re-run, never sends a second pick list.
const seen = $getWorkflowStaticData('global').sent || [];
return $input.all().map(i => ({ json: Object.assign({}, i.json, { duplicate: seen.includes(i.json.order_id) }) }));

// Only after the email succeeded. Keeps the last 1000 order ids.
const sd = $getWorkflowStaticData('global'), seen = sd.sent || [];
for (const i of $('Ship it?').all()) if (!seen.includes(i.json.order_id)) seen.push(i.json.order_id);
sd.sent = seen.slice(-1000);
return $('Ship it?').all().map(i => ({ json: i.json }));

// One alert for every failure path. $prevNode names the step that failed.
const cfg = $('Config').first().json;
return $input.all().map(i => {
  const e = i.json.error;
  const msg = String((typeof e === 'string' ? e : e && (e.description || e.message)) || i.json.message || JSON.stringify(i.json)).slice(0, 400);
  return { json: { text: `${cfg.workflow_label}: ${$prevNode.name} failed${i.json.ref ? ' for ' + i.json.ref : ''}. ${msg}` } };
});
